"""Run official validation against an isolated combined API, PostgreSQL and worker."""

from __future__ import annotations

import argparse
import hashlib
import html
import json
import os
import shlex
import socket

# Fixed executable/argument vectors, never a shell.
import subprocess  # nosec B404
import sys
from collections import Counter
from datetime import UTC, datetime
from pathlib import Path
from uuid import uuid4

# Only reports generated by our isolated pinned test container are parsed.
from xml.etree import ElementTree as ET  # nosec B405
from zipfile import ZIP_DEFLATED, ZipFile, is_zipfile

import yaml
from pygeoapi.util import yaml_load

ROOT = Path(__file__).resolve().parents[1]
SETTINGS = ROOT / "validation/cite-teamengine/runner.json"
CLASS_NAME = "test_processes.cite_echo.CiteEchoProcessor"


class InfrastructureError(RuntimeError):
    """The validator could not produce a complete test run."""


def command(arguments, *, environment=None, log=None, timeout=900):
    """Invoke a fixed executable/argument vector and preserve failures."""
    try:
        result = subprocess.run(  # nosec B603
            arguments, cwd=ROOT, env=environment, capture_output=True, text=True, timeout=timeout, check=False
        )
    except (OSError, subprocess.TimeoutExpired) as error:
        raise InfrastructureError(str(error)) from error
    if log is not None:
        log.write_text(result.stdout + result.stderr)
    if result.returncode:
        raise InfrastructureError(
            f"{shlex.join(arguments)} exited {result.returncode}: {(result.stderr or result.stdout)[-3000:]}"
        )
    return result.stdout.strip()


def prepare_config(destination, *, password="cite-test-only", echo=True, public_url="http://api:8080"):
    """Copy canonical runtime wiring and optionally register the test-only echo."""
    with (ROOT / "config/pygeoapi.yml").open() as stream:
        config = yaml_load(stream)
    original_url = config["server"]["url"].rstrip("/")
    config["server"]["logo"] = config["server"]["logo"].replace(original_url, public_url, 1)
    config["server"]["url"] = public_url
    config["metadata"]["identification"]["url"] = public_url
    for name in ("sample-points", "sample-polygons"):
        for provider in config["resources"][name]["providers"]:
            provider["data"] = "/pygeoapi/geo_processes/data/samples/" + Path(provider["data"]).name
        for link in config["resources"][name].get("links", []):
            link["href"] = link["href"].replace(original_url, public_url, 1)
    config["server"]["manager"]["name"] = "geo_processes.async_manager.DurableProcessManager"
    config["server"]["manager"]["connection"] = f"postgresql://geo:{password}@db:5432/geo"
    if echo:
        config["resources"]["cite-echo"] = {"type": "process", "processor": {"name": CLASS_NAME}}
    destination.write_text(yaml.safe_dump(config, sort_keys=False, allow_unicode=True))
    return config


def summarize(path):
    """Read the unmodified TestNG report; configuration errors are not passes."""
    try:
        root = ET.parse(path).getroot()  # nosec B314
    except (OSError, ET.ParseError) as error:
        raise InfrastructureError(f"Unreadable TestNG report: {error}") from error
    if root.tag != "testng-results" or root.find("suite") is None:
        raise InfrastructureError("Not a native TestNG results document")
    cases = []
    configuration_failures = []
    for group in root.findall("./suite/test"):
        for test_class in group.findall("class"):
            for method in test_class.findall("test-method"):
                case = {
                    "group": group.get("name"),
                    "class": test_class.get("name"),
                    "name": method.get("name"),
                    "status": method.get("status"),
                    "requirement": method.get("description", "").strip(),
                    "message": (method.findtext("exception/message") or "").strip(),
                }
                if method.get("is-config") == "true":
                    if case["status"] == "FAIL":
                        configuration_failures.append(case)
                    continue
                if not all(case[field] for field in ("group", "class", "name")):
                    raise InfrastructureError("TestNG test case is missing its identity")
                if case["status"] not in {"PASS", "FAIL", "SKIP"}:
                    raise InfrastructureError(f"Unexpected test status: {case['status']}")
                cases.append(case)
    if not cases:
        raise InfrastructureError("CITE produced no executable test cases")
    counts = Counter(case["status"] for case in cases)
    for field, status in (("passed", "PASS"), ("failed", "FAIL"), ("skipped", "SKIP")):
        if int(root.get(field, "-1")) != counts[status]:
            raise InfrastructureError(f"TestNG {field} total does not match individual cases")
    return {
        "suite": root.find("suite").get("name"),
        "counts": {status: counts[status] for status in ("PASS", "FAIL", "SKIP")},
        "configurationFailures": configuration_failures,
        "cases": sorted(cases, key=lambda case: (case["group"], case["class"], case["name"])),
    }


def official_reports(directory, native_report):
    """Require TEAM Engine's own HTML and ZIP from the same native test run."""
    paths = {
        "officialHtmlReport": native_report.parent / "result/index.html",
        "nativeHtmlArchive": native_report.parent / "result.zip",
    }
    for path in paths.values():
        if not path.is_file() or not path.stat().st_size:
            raise InfrastructureError(f"Missing or empty official TEAM Engine report: {path}")
    if not is_zipfile(paths["nativeHtmlArchive"]):
        raise InfrastructureError("Official TEAM Engine HTML archive is not a valid ZIP")
    # TEAM Engine 6.0.0-RC2's ZIP flattens js/ and styles/. Keep it unmodified,
    # but also package the unchanged official report with working relative paths.
    paths["officialHtmlArchive"] = directory / "official-report.zip"
    result_directory = paths["officialHtmlReport"].parent
    with ZipFile(paths["officialHtmlArchive"], "w", compression=ZIP_DEFLATED) as archive:
        for path in sorted(result_directory.rglob("*")):
            if path.is_file():
                archive.write(path, path.relative_to(result_directory))
    return {name: path.relative_to(directory).as_posix() for name, path in paths.items()}


def write_reports(directory, summary, metadata):
    (directory / "summary.json").write_text(json.dumps(summary, indent=2) + "\n")
    (directory / "metadata.json").write_text(json.dumps(metadata, indent=2) + "\n")
    counts = summary["counts"]
    lines = [
        "# CITE observation",
        "",
        f"{counts['PASS']} passed; {counts['FAIL']} failed; {counts['SKIP']} skipped.",
        "",
    ]
    report_links = ""
    if official := metadata.get("officialHtmlReport"):
        archive = metadata["officialHtmlArchive"]
        lines += [f"[Official TEAM Engine HTML report]({official}) · [HTML ZIP]({archive})", ""]
        report_links = (
            f'<p><a href="{html.escape(official, quote=True)}">Official TEAM Engine HTML report</a> · '
            f'<a href="{html.escape(archive, quote=True)}">HTML ZIP</a></p>'
        )
    for case in summary["cases"]:
        if case["status"] != "PASS":
            lines += [f"## {case['status']}: {case['name']}", "", case["requirement"], "", case["message"], ""]
    (directory / "summary.md").write_text("\n".join(lines))
    rows = "".join(
        f"<tr><td>{html.escape(case['group'])}</td><td>{html.escape(case['status'])}</td>"
        f"<td>{html.escape(case['name'])}</td><td><pre>{html.escape(case['message'])}</pre></td></tr>"
        for case in summary["cases"]
    )
    (directory / "summary.html").write_text(
        '<!doctype html><meta charset="utf-8"><title>CITE results</title><h1>CITE observation</h1>'
        f"<p>{counts['PASS']} passed; {counts['FAIL']} failed; {counts['SKIP']} skipped.</p>"
        f"{report_links}"
        f"<table><tr><th>Class</th><th>Status</th><th>Test</th><th>Details</th></tr>{rows}</table>"
    )


def source_fingerprint():
    digest = hashlib.sha256()
    paths = [
        ROOT / "pyproject.toml",
        ROOT / "uv.lock",
        ROOT / "docker/Dockerfile",
        ROOT / "docker/entrypoint.sh",
        ROOT / "tests/fixtures/test_processes/cite_echo.py",
    ]
    paths.extend(
        path for path in (ROOT / "src/geo_processes").rglob("*") if path.is_file() and "__pycache__" not in path.parts
    )
    for path in sorted(paths):
        digest.update(str(path.relative_to(ROOT)).encode())
        digest.update(path.read_bytes())
    return digest.hexdigest()


def run(*, browser=False, geonovum=False):
    settings = json.loads(SETTINGS.read_text())
    validator = "geonovum" if geonovum else "cite"
    project = f"raster-{validator}-" + uuid4().hex[:12]
    directory = ROOT / "runtime-data" / validator / project
    directory.mkdir(parents=True)
    (directory / "reports").mkdir()
    password = uuid4().hex
    port = 0
    public_url = "http://api:8080"
    if geonovum:
        with socket.socket() as listener:
            listener.bind(("127.0.0.1", 0))
            port = listener.getsockname()[1]
        public_url = f"http://127.0.0.1:{port}"
    config = prepare_config(directory / "api-config.yml", password=password, echo=not geonovum, public_url=public_url)
    parameters = {
        "iut": public_url,
        "echoprocessid": "cite-echo",
        "testallprocesses": "on",
        "processtestlimit": "0",
        # The official executor also retains XML/EARL when producing its HTML ZIP.
        "acceptMediaType": "application/zip",
    }
    properties = ET.Element("properties")
    for key, value in parameters.items():
        ET.SubElement(properties, "entry", key=key).text = value
    ET.ElementTree(properties).write(directory / "test-run-props.xml", encoding="utf-8", xml_declaration=True)
    environment = {
        **os.environ,
        "GEO_JOB_PASSWORD": password,
        "CITE_API_PORT": str(port),
        "CITE_PUBLIC_URL": public_url,
        "CITE_RUN_DIR": str(directory),
        "CITE_IMAGE": settings["image"],
        "CITE_API_IMAGE": project + ":test",
        "CITE_UID": str(os.getuid()),
        "CITE_GID": str(os.getgid()),
    }
    compose = ["docker", "compose", "--project-name", project, "--file", "compose.cite.yml"]
    metadata = {
        **settings,
        "project": project,
        "started": datetime.now(UTC).isoformat(),
        "parameters": parameters,
        "applicationCommit": command(["git", "rev-parse", "HEAD"]),
        "workingTreeDirty": bool(command(["git", "status", "--porcelain"])),
        "applicationSourceSha256": source_fingerprint(),
        "configurationSha256": hashlib.sha256((directory / "api-config.yml").read_bytes()).hexdigest(),
        "composeSha256": hashlib.sha256((ROOT / "compose.cite.yml").read_bytes()).hexdigest(),
        "composeBaseSha256": hashlib.sha256((ROOT / "compose.base.yml").read_bytes()).hexdigest(),
        "manager": config["server"]["manager"]["name"],
        "processes": [name for name, resource in config["resources"].items() if resource["type"] == "process"],
        "composeVersion": command(["docker", "compose", "version", "--short"]),
        "mode": "browser" if browser else validator,
        "deployment": "combined",
    }
    (directory / "metadata.json").write_text(json.dumps(metadata, indent=2) + "\n")
    keep = False
    exit_code = 2
    print(f"Validation project: {project}\nReports: {directory}", flush=True)
    try:
        print("Building and starting the isolated application", flush=True)
        command(
            [*compose, "up", "--build", "--wait", "--wait-timeout", "120", "api", "worker"],
            environment=environment,
            log=directory / "application-start.log",
        )
        metadata["applicationImage"] = json.loads(
            command(["docker", "image", "inspect", environment["CITE_API_IMAGE"]])
        )[0]["Id"]
        wire = command(
            [
                *compose,
                "exec",
                "-T",
                "api",
                "/venv/bin/python3",
                "-c",
                "import json,urllib.request; "
                "print(json.dumps({name:json.load(urllib.request.urlopen('http://localhost:8080/'+path)) "
                "for name,path in [('conformance','conformance'),('processes','processes?f=json'),"
                "('openapi','openapi?f=json')]}))",
            ],
            environment=environment,
        )
        (directory / "discovery.json").write_text(wire + "\n")
        metadata["advertisedConformance"] = json.loads(wire)["conformance"]["conformsTo"]
        for script, log_name in (("smoke_inputs.py", "raster-smoke.log"), ("smoke_async.py", "async-smoke.log")):
            arguments = (
                [sys.executable, str(ROOT / "scripts" / script)]
                if geonovum
                else [
                    *compose,
                    "exec",
                    "-T",
                    "-e",
                    "PYTHONPATH=/pygeoapi:/validation",
                    "api",
                    "/venv/bin/python3",
                    f"/validation/scripts/{script}",
                ]
            )
            command([*arguments, "--base-url", public_url], environment=environment, log=directory / log_name)
        metadata["asyncSmokePassed"] = True
        if browser:
            command(
                [*compose, "--profile", "browser", "up", "--detach", "browser"],
                environment=environment,
                log=directory / "browser-start.log",
            )
            port = command([*compose, "port", "browser", "8080"], environment=environment)
            metadata["browserUrl"] = f"http://{port}/teamengine/"
            cleanup = [
                "env",
                *(f"{key}={environment[key]}" for key in ("CITE_RUN_DIR", "CITE_IMAGE", "CITE_API_IMAGE")),
                *compose,
                "--profile",
                "browser",
                "down",
                "--volumes",
                "--remove-orphans",
            ]
            metadata["cleanupCommand"] = shlex.join(cleanup)
            metadata["cleanupImageCommand"] = shlex.join(
                ["docker", "image", "rm", "--no-prune", environment["CITE_API_IMAGE"]]
            )
            (directory / "metadata.json").write_text(json.dumps(metadata, indent=2) + "\n")
            print(
                f"Browser fallback: {metadata['browserUrl']} (ogctest / ogctest)\n"
                "No automated CITE result is claimed.\n"
                f"Cleanup: {metadata['cleanupCommand']}\n"
                f"Remove test image: {metadata['cleanupImageCommand']}",
                flush=True,
            )
            keep = True
            return 0
        if geonovum:
            from scripts import check_geonovum_baseline

            port = command([*compose, "port", "api", "8080"], environment=environment)
            exit_code = check_geonovum_baseline.main(
                [
                    "--docker",
                    "--input",
                    f"http://{port}/openapi?f=json",
                    "--raw-output",
                    str(directory / "geonovum.json"),
                ]
            )
        else:
            print("Running the official CITE CLI", flush=True)
            command([*compose, "run", "--rm", "cite"], environment=environment, log=directory / "cite-cli.log")
            metadata["validatorImage"] = json.loads(command(["docker", "image", "inspect", settings["image"]]))[0]["Id"]
            reports = list((directory / "reports").rglob("testng-results.xml"))
            if len(reports) != 1:
                raise InfrastructureError(f"Expected one native TestNG report; found {len(reports)}")
            summary = summarize(reports[0])
            if summary["suite"] != f"{settings['suite']}-{settings['suiteVersion']}":
                raise InfrastructureError(f"Unexpected suite version in report: {summary['suite']}")
            metadata.update(official_reports(directory, reports[0]))
            metadata["finished"] = datetime.now(UTC).isoformat()
            write_reports(directory, summary, metadata)
            print(f"Official TEAM Engine HTML: {directory / metadata['officialHtmlReport']}", flush=True)
            print(f"Shareable official report ZIP: {directory / metadata['officialHtmlArchive']}", flush=True)
            print(f"CITE: {summary['counts']}", flush=True)
            for case in summary["cases"]:
                if case["status"] == "FAIL":
                    print(f"FAIL {case['name']}: {case['message']}", flush=True)
            exit_code = 1 if summary["counts"]["FAIL"] or summary["configurationFailures"] else 0
    except InfrastructureError as error:
        print(f"INFRASTRUCTURE ERROR: {error}", file=sys.stderr)
        (directory / "infrastructure-error.txt").write_text(str(error) + "\n")
        exit_code = 2
    finally:
        if not keep:
            # A log collection failure must not prevent the actual teardown.
            for arguments, log in (
                ([*compose, "logs", "--no-color", "api", "worker", "db"], directory / "application.log"),
                (
                    [*compose, "--profile", "browser", "down", "--volumes", "--remove-orphans"],
                    directory / "cleanup.log",
                ),
                (
                    ["docker", "image", "rm", "--no-prune", environment["CITE_API_IMAGE"]],
                    directory / "image-cleanup.log",
                ),
            ):
                try:
                    command(arguments, environment=environment, log=log)
                except InfrastructureError as error:
                    print(f"INFRASTRUCTURE ERROR during cleanup: {error}", file=sys.stderr)
                    exit_code = 2
    metadata["finished"] = datetime.now(UTC).isoformat()
    metadata["exitCode"] = exit_code
    (directory / "metadata.json").write_text(json.dumps(metadata, indent=2) + "\n")
    return exit_code


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    modes = parser.add_mutually_exclusive_group()
    modes.add_argument(
        "--browser", action="store_true", help="Leave an isolated browser fallback running; print its cleanup command"
    )
    modes.add_argument("--geonovum", action="store_true", help="Run Geonovum against the isolated combined deployment")
    args = parser.parse_args()
    try:
        return run(browser=args.browser, geonovum=args.geonovum)
    except (InfrastructureError, OSError, ValueError, ET.ParseError) as error:
        print(f"INFRASTRUCTURE ERROR: {error}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
